#!/usr/bin/env bash
#
# START modification - generated by AI (GitHub Copilot, DeepSeek V4 Flash)
#
# device-appdata.sh — back up / restore the UPM app data on a physical device.
#
# The password vault lives in /data/data/com.u17od.upm/files/upm.db, so protect
# it before any uninstall/reinstall (see scripts/device-reinstall.sh). Reading
# the vault needs a debuggable build; run-as works on a debug install.
#
#   scripts/device-appdata.sh backup  [SERIAL] [TARBALL]
#   scripts/device-appdata.sh restore [SERIAL] [TARBALL]
#   scripts/device-appdata.sh list    [TARBALL]
#
# Emulators are ignored when picking SERIAL, like install-on-device.sh: they are
# handled by emulator-run.sh instead.
#
set -euo pipefail

APP_ID="com.u17od.upm"
DEFAULT_TARBALL="/tmp/upm-appdata.tar"

step() { printf '\n==> %s\n' "$*"; }
info() { printf '    %s\n' "$*"; }
die()  { printf '[error] %s\n' "$*" >&2; exit 1; }

pick_serial() {
    local found count
    found="$(adb devices | awk '$1 !~ /^emulator-/ && $2 == "device" { print $1 }')"
    count="$(printf '%s\n' "$found" | grep -c '^[^[:space:]]' || true)"
    (( count == 1 )) || die "need exactly one physical device (found $count) — pass SERIAL"
    printf '%s' "$found"
}

command -v adb >/dev/null 2>&1 || die "adb is not on PATH"

CMD="${1:-}"
shift || true
[[ -n "$CMD" ]] || die "usage: device-appdata.sh {backup|restore|list} [SERIAL] [TARBALL]"

case "$CMD" in
    backup)
        SERIAL="${1:-$(pick_serial)}"
        TARBALL="${2:-$DEFAULT_TARBALL}"
        step "Backing up /data/data/$APP_ID on $SERIAL -> $TARBALL"
        adb -s "$SERIAL" exec-out run-as "$APP_ID" tar cf - . > "$TARBALL"
        [[ -s "$TARBALL" ]] || die "backup is empty (is the build debuggable and installed?)"
        tar tvf "$TARBALL"
        info "$(wc -c < "$TARBALL") bytes"
        ;;
    restore)
        SERIAL="${1:-$(pick_serial)}"
        TARBALL="${2:-$DEFAULT_TARBALL}"
        [[ -f "$TARBALL" ]] || die "no such tarball: $TARBALL"
        step "Restoring $TARBALL on $SERIAL"
        adb -s "$SERIAL" shell run-as "$APP_ID" tar xf - < "$TARBALL"
        adb -s "$SERIAL" shell run-as "$APP_ID" ls -la files/ shared_prefs/
        ;;
    list)
        TARBALL="${1:-$DEFAULT_TARBALL}"
        [[ -f "$TARBALL" ]] || die "no such tarball: $TARBALL"
        tar tvf "$TARBALL"
        ;;
    *)
        die "unknown command: $CMD"
        ;;
esac

step "Done"
# END modification - generated by AI (GitHub Copilot, DeepSeek V4 Flash)
